# Q25 round-2 patch (idempotent; run after build_report_q25.py): bowl/window/MRS systematics. python3 -I build_report_q25_fix.py
import json
p='/output/report.json'; r=json.load(open(p)); R=r['results']
MARK='[round2 systematics] '
R=[x for x in R if not x['quantity'].startswith('Q25d')]
for x in R:
    q=x['quantity']
    if q.startswith('Q25a') and MARK not in x['value']:
        x['quantity']='Q25a: HCN/HCO+ 1-0 disk ratio at 10" beam, annuli 0-4/4-8/6-9/8-12": Michiyama 0.645/0.619/0.602/0.559 (no zero-level correction; 0.650/0.628/0.615/0.589 with maximal bowl add-back), Harada 0.648/0.610/0.576/0.447 (recovery-limited, not trusted at 8-12")'
        x['value']=MARK+'8-12/4-8 decline factor, Michiyama 1-0: 0.902 (no correction) to 0.937 (maximal uniform bowl add-back = -mean of the 22-35" ring: -0.59 HCN, -0.73 HCO+ Jy/beam km/s) => decline 6-10% (not 10+-1.6%). Window +-250/350/500 km/s changes it by <0.001 (0.902/0.902/0.901). Per-channel (annulus spectra): the bowl exists only at line velocities (-2 to -3 mJy/beam at 10" vs +14-16 mJy HCN and 25-28 mJy HCO+ in the 8-12" ring), the line-free windows have mean offset <0.1 Jy/beam km/s (rms 0.05): the bowl is a line-proportional negative, as expected from missing short spacings, so a constant add-back is an upper bound on the correction only if there is no real emission at 22-35" (otherwise the true bowl is larger). Harada: 0.733 (to 0.78 with add-back; window-dependent 0.76/0.73/0.66 for +-250/350/500, ring std 1.8-2.5, i.e. unreliable) - rejected at 8-12". uv properties: only images are available (no visibilities restored, MRS not in the headers); both 1-0 sets are 12m-only Cycle-3 (2.1" and 1.4" beams), minimum baseline ~15m (4.4 kl) => MRS ~10-30" depending on configuration (not measured); Fourier ratio Harada/Michiyama of the 10" maps is 0.6-0.7 at 1-4 kl and >1.3 above 4 kl (log q25_growth.log), i.e. Harada under-represents the 50-200" scales (and over-weights small scales in the normalisation); the Harada cumulative flux is 0.75-0.78 of that of Michiyama inside 12" and 0.5-0.57 inside 20". Michiyama is preferred because Xb55 and Michiyama both pass the high-pass 0.5-3 kl test with a stable 8-12/4-8 factor (0.90-0.92, 0.89-0.86), not because it has more flux; neither dataset is complete (cumulative flux falls beyond 16" in both). Literature: Harada+2018 give per-nucleus 1-0 ratios only; no disk ring value published.'
        x['uncertainty']='statistical +-0.016 on the factor; zero-level systematic +0.00/+0.035 (dominant, 2x the statistic); 8-12" Harada recovery-limited'
        x['confidence']='medium'
        x['evidence']+='; scripts/q25_systematics.py -> out/q25/q25_systematics.log'
    if q.startswith('Q25b') and MARK not in x['value']:
        x['quantity']='Q25b: 1-0 and 2-1 HCN/HCO+ disk ratios decline alike within the zero-level systematic: 8-12/4-8 factor 0.90-0.94 (1-0, Michiyama) vs 0.89-0.91 (2-1, Xb55); R21/R10 flat to -5/+1%'
        x['value']=MARK+'Answer to Q25: yes, the 8-12" HCN/HCO+ decline is seen in 1-0 as in 2-1, but both are upper bounds: decline 6-10% (1-0) and 9-11% (2-1; 0.889 uncorrected, 0.895 with the 22-35" ring offset, which lies outside the 2-1 primary beam half-power so poorly constrained, and 0.914 with the reviewer cumulative-flux (16-30") upper bound). Difference of the factors (1-0 minus 2-1) lies in -0.012...+0.048 for combinations of corrections between zero and maximal; R21/R10(8-12")/R21/R10(4-8") = 0.99 (no corrections) / 0.98 (both maximal) / 0.95-1.01 (corrections applied to one band only) => the ladder ratio is flat within 5%, and a decline of 6-11% in both transitions cannot be separated from zero-level and uv-recovery effects at the 3-5% level; the 1-0 data do not support an extra excitation drop (opposite of the 3-2 of Q11) nor exclude 1-0 declining less (6%). Original ladders (Tb, Michiyama): HCN 2-1/1-0 0.567/0.496/0.523/0.436 and HCO+ 0.632/0.555/0.586/0.495, i.e. 0-4 -> 8-12" falls ~22-23% for both species; the offset add-back raises the 8-12" fluxes more in 1-0 than 2-1 (factor 0.937 vs 0.895-0.914), so the 1-0 ladder at 8-12" would be 3-5% lower relative to 4-8" than quoted. Harada ladder (0.97 HCN, 0.88 HCO+ at 8-12") unphysical => Harada 8-12" flux incomplete.'
        x['uncertainty']='R21/R10 stat +-0.01; zero-level +-0.05 (relative) on ratio-of-factors; 10% cross-band flux scale on ladders'
    if q.startswith('Q25c') and MARK not in x['value']:
        x['value']=MARK+'Softened: the RADEX statement stands only at its resolution. The ring-to-ring R21/R10 is flat within +-5% under all zero-level scenarios; a 5% change in R21 corresponds to ~0.02 dex in log X (earlier estimate: 15% -> ~0.07 dex) and far less than the 0.25 dex grid step, so the fit result (log X = +0.50 constant, delta log X=0.00 +-0.25; allowed outer density decrease 0-0.5 dex) is unchanged; the fit was not re-run per scenario. No abundance gradient and no excitation change is REQUIRED by the 1-0/2-1 data; a 0-0.5 dex lower n at 8-12" is allowed. '+x['value']
    if q.startswith('Q11') and 'upper bound' not in x['value'] and ('2-1' in q or 'Q11a' in q or 'Q11d' in q):
        x['value']+=' [Q25 note: the 2-1 8-12/4-8 decline (11%) is an upper bound: adding back the maximal uniform bowl estimated from the cumulative flux (16-30") gives 0.914 (decline 8.6%); the 22-35" ring-mean offset gives 0.895 (10.5%); the same bowl-like negative pattern is present in the Michiyama 1-0 (6-10%). See Q25.]'
R.append({"quantity":"Q25d: zero-level (bowl) and window systematics on the 8-12/4-8 HCN/HCO+ factor, with scenario table","target":"disk, 8-12\"",
 "value":"factor (8-12 over 4-8 ratio): Michiyama 1-0: 0.902 / 0.921 / 0.937 for 0 / 0.5 / 1.0 of the offset (ring 22-35\" mean); Harada 1-0 0.733/0.759/0.779; Xb55 2-1 0.889/0.892/0.895 (ring beyond PB), 0.914 for reviewer's cumulative-flux (16-30\") bound. Window +-250/350/500: Michiyama 0.902/0.902/0.901, Xb55 0.887/0.889/0.898, Harada 0.757/0.733/0.663. Line-free window means: |mean| <= 0.12 Jy/beam km/s (rms 0.05-0.1). 8-12\" annulus spectra of HCN and HCO+ (Michiyama, 26 km/s channels): same velocity extent (FWHM ~200 km/s; peaks 16.5 and 28.5 mJy), no wings beyond +-350 km/s above the 0.3 mJy noise.",
 "uncertainty":"offset scenarios: factor +0 to +0.035 (1-0), +0 to +0.025 (2-1)","unit":"ratio","confidence":"medium",
 "evidence":"scripts/q25_systematics.py -> out/q25/q25_systematics.log; team/checks/q25_bowl_estimate.py","assumptions":R[-1]['assumptions'] if False else [{"name":"offset model","value":"constant negative offset added to every pixel of the 10\" moment-0 map; maximal = minus the 22-35\" ring mean; upper bound on correction unless real emission lies in the ring"}]})
r['results']=R; json.dump(r,open(p,'w'),indent=1)
